<section class="content-area" aria-labelledby="page-title"><div class="container-fluid"><h1 id="page-title" class="h3 mb-2">Triage Rules</h1><p class="text-muted mb-4">Manage keyword groups for the local prototype. Urgent signals always take priority.</p><div class="row g-4"><?php foreach ($rules as $rule): ?><div class="col-xl-4"><section class="card h-100 triage-panel triage-panel--<?= htmlspecialchars($rule->tier, ENT_QUOTES, 'UTF-8') ?>"><div class="card-body"><h2 class="h5"><?= htmlspecialchars($rule->label, ENT_QUOTES, 'UTF-8') ?></h2><ul class="keyword-chips list-unstyled d-flex flex-wrap gap-2" aria-label="<?= htmlspecialchars($rule->label, ENT_QUOTES, 'UTF-8') ?> keywords"><?php foreach ($rule->keywords as $keyword): ?><li><button class="keyword-chip" type="button" aria-label="Remove keyword <?= htmlspecialchars($keyword, ENT_QUOTES, 'UTF-8') ?>"><span><?= htmlspecialchars($keyword, ENT_QUOTES, 'UTF-8') ?></span><span aria-hidden="true"> ×</span></button></li><?php endforeach; ?></ul><form class="keyword-form d-flex gap-2" data-tier="<?= htmlspecialchars($rule->tier, ENT_QUOTES, 'UTF-8') ?>"><label class="visually-hidden" for="keyword-<?= htmlspecialchars($rule->tier, ENT_QUOTES, 'UTF-8') ?>">Add keyword</label><input id="keyword-<?= htmlspecialchars($rule->tier, ENT_QUOTES, 'UTF-8') ?>" class="form-control" maxlength="50" required placeholder="Add keyword"><button class="btn btn-outline-primary" type="submit">Add</button></form><?php if ($rule->tier === 'urgent'): ?><p class="small text-danger mt-3 mb-0">Urgent messages display the instruction to call 190 (SAMU).</p><?php endif; ?></div></section></div><?php endforeach; ?></div></div></section>
